import os
import threading

def job():
    print("pid", os.getpid(), "thread", threading.get_ident(), flush=True)

pid = os.fork()
if pid == 0:
    workers = [threading.Thread(target=job) for index in range(2)]
    for worker in workers:
        worker.start()
    for worker in workers:
        worker.join()
    os._exit(0)
os.waitpid(pid, 0)

